<section class="content-area" aria-labelledby="page-title"><div class="container-fluid"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 id="page-title" class="h3">Knowledge Base</h1><p class="text-muted mb-0">Educational entries used by the assistant prototype.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#entryModal" type="button">Add entry</button></div><div class="card"><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Topic</th><th>Summary</th><th>Source</th><th>Triage tier</th><th>Last updated</th><th>Actions</th></tr></thead><tbody><?php foreach ($entries as $entry): ?><tr><td><?= htmlspecialchars($entry->topic, ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($entry->summary, ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($entry->source, ENT_QUOTES, 'UTF-8') ?></td><td><span class="triage-badge triage-badge--<?= htmlspecialchars($entry->tier, ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars($entry->tier === 'consult' ? 'Consult a professional' : ucfirst($entry->tier), ENT_QUOTES, 'UTF-8') ?></span></td><td><?= htmlspecialchars($entry->updated, ENT_QUOTES, 'UTF-8') ?></td><td class="text-nowrap"><button class="btn btn-sm btn-outline-primary" type="button" data-edit-entry="<?= (int)$entry->id ?>" data-topic="<?= htmlspecialchars($entry->topic, ENT_QUOTES, 'UTF-8') ?>" data-summary="<?= htmlspecialchars($entry->summary, ENT_QUOTES, 'UTF-8') ?>" data-source="<?= htmlspecialchars($entry->source, ENT_QUOTES, 'UTF-8') ?>" data-tier="<?= htmlspecialchars($entry->tier, ENT_QUOTES, 'UTF-8') ?>">Edit</button> <button class="btn btn-sm btn-outline-danger" type="button" data-delete-entry="<?= (int)$entry->id ?>">Delete</button></td></tr><?php endforeach; ?></tbody></table></div></div></div></div></section>
<div class="modal fade" id="entryModal" tabindex="-1" aria-labelledby="entryModalTitle" aria-hidden="true"><div class="modal-dialog"><form class="modal-content needs-validation" id="entryForm" novalidate><div class="modal-header"><h2 class="modal-title fs-5" id="entryModalTitle">Add knowledge entry</h2><button class="btn-close" type="button" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><input type="hidden" id="entryId"><div class="mb-3"><label class="form-label" for="entryTopic">Topic</label><input class="form-control" id="entryTopic" required><div class="invalid-feedback">Enter a topic.</div></div><div class="mb-3"><label class="form-label" for="entrySummary">Summary</label><textarea class="form-control" id="entrySummary" rows="3" required></textarea><div class="invalid-feedback">Enter a summary.</div></div><div class="mb-3"><label class="form-label" for="entrySource">Source</label><select class="form-select" id="entrySource" required><?php foreach ($sources as $source): ?><option><?= htmlspecialchars($source->label, ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div><label class="form-label" for="entryTier">Triage tier</label><select class="form-select" id="entryTier"><option value="informational">Informational</option><option value="consult">Consult a professional</option><option value="urgent">Urgent</option></select></div></div><div class="modal-footer"><button class="btn btn-secondary" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary" type="submit">Save entry</button></div></form></div></div>
<div class="modal fade" id="deleteEntryModal" tabindex="-1" aria-labelledby="deleteEntryTitle" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h2 class="modal-title fs-5" id="deleteEntryTitle">Delete entry?</h2><button class="btn-close" type="button" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body">This removes the entry from the current demo table.</div><div class="modal-footer"><button class="btn btn-secondary" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-danger" type="button" id="confirmDeleteEntry">Delete</button></div></div></div></div>
